import 'package:geolocator/geolocator.dart'; class LocationService{Future<Position> current()async{if(!await Geolocator.isLocationServiceEnabled())throw StateError('GPS belum aktif.');var p=await Geolocator.checkPermission();if(p==LocationPermission.denied)p=await Geolocator.requestPermission();if(p==LocationPermission.denied||p==LocationPermission.deniedForever)throw StateError('Izin lokasi diperlukan.');return Geolocator.getCurrentPosition();}}